const item = $input.first().json;
const missing = [];
if (item.workspace_id === undefined || item.workspace_id === null || item.workspace_id === '') missing.push('workspace_id');
if (!item.research_topic) missing.push('research_topic');
if (!item.research_question) missing.push('research_question');
if (!Array.isArray(item.keywords) || item.keywords.length === 0) missing.push('keywords');
if (!item.search_preferences || typeof item.search_preferences !== 'object' || Array.isArray(item.search_preferences)) missing.push('search_preferences');
return [{ json: Object.assign({}, item, { is_valid: missing.length === 0, missing_fields: missing }) }];

const item = $input.first().json;
const topic = (item.research_topic || '').toString().trim();
const question = (item.research_question || '').toString().trim();
const kws = Array.isArray(item.keywords) ? item.keywords.map(function (k) { return (k || '').toString().trim(); }).filter(Boolean) : [];
const prefs = (item.search_preferences && typeof item.search_preferences === 'object') ? item.search_preferences : {};
const topKws = kws.slice(0, 5);
const primary = [topic].concat(topKws).filter(Boolean).join(' ').trim();
const secondary = [topic, question].filter(Boolean).join(' ').trim();
const queries = Array.from(new Set([primary, secondary].filter(Boolean)));
let maxResults = Number(prefs.max_results);
if (!Number.isFinite(maxResults) || maxResults <= 0) maxResults = 20;
if (maxResults > 50) maxResults = 50;
const yearFrom = prefs.year_from ? Number(prefs.year_from) : null;
const yearTo = prefs.year_to ? Number(prefs.year_to) : null;
let yearRange = '';
if (yearFrom && yearTo) yearRange = yearFrom + '-' + yearTo;
else if (yearFrom) yearRange = yearFrom + '-';
else if (yearTo) yearRange = '-' + yearTo;
const arxivQuery = 'all:' + (primary || topic || question);
const ssQuery = primary || secondary || topic || question;
return [{ json: {
  workspace_id: Number(item.workspace_id),
  research_topic: topic,
  research_question: question,
  keywords: kws,
  search_preferences: prefs,
  queries: queries,
  arxiv_query: arxivQuery,
  ss_query: ssQuery,
  year_range: yearRange,
  max_results: maxResults
} }];

const cfg = $('Build Search Queries').first().json;
const wsId = Number(cfg.workspace_id);
const prefs = (cfg.search_preferences && typeof cfg.search_preferences === 'object') ? cfg.search_preferences : {};
const yearFrom = prefs.year_from ? Number(prefs.year_from) : null;
const yearTo = prefs.year_to ? Number(prefs.year_to) : null;

const terms = [];
function pushTerms(s) {
  if (!s) return;
  const m = s.toString().toLowerCase().match(/[a-z0-9]+/g) || [];
  m.forEach(function (t) { if (t.length > 2) terms.push(t); });
}
pushTerms(cfg.research_topic);
pushTerms(cfg.research_question);
(Array.isArray(cfg.keywords) ? cfg.keywords : []).forEach(pushTerms);
const uniqTerms = Array.from(new Set(terms));

function scoreOf(title, abstract) {
  if (uniqTerms.length === 0) return 0;
  const hay = ((title || '') + ' ' + (abstract || '')).toLowerCase();
  let hits = 0;
  uniqTerms.forEach(function (t) { if (hay.indexOf(t) !== -1) hits++; });
  return Math.round((hits / uniqTerms.length) * 100) / 100;
}

const papers = [];

// arXiv
let arxivEntries = [];
try {
  const parsed = $('Parse arXiv Response').first().json;
  const feed = parsed && parsed.feed ? parsed.feed : parsed;
  const entry = feed ? feed.entry : undefined;
  if (entry) arxivEntries = Array.isArray(entry) ? entry : [entry];
} catch (e) { arxivEntries = []; }

arxivEntries.forEach(function (e) {
  if (!e) return;
  const idUrl = (e.id || '').toString();
  let arxivId = '';
  const m = idUrl.match(/abs\/(.+?)(v\d+)?$/);
  if (m) arxivId = m[1];
  const title = (e.title || '').toString().replace(/\s+/g, ' ').trim();
  const abstract = (e.summary || '').toString().replace(/\s+/g, ' ').trim();
  let authors = [];
  if (e.author) {
    const al = Array.isArray(e.author) ? e.author : [e.author];
    authors = al.map(function (a) { return { name: a && a.name ? a.name : (typeof a === 'string' ? a : '') }; }).filter(function (a) { return a.name; });
  }
  const published = (e.published || '').toString();
  const pubDate = published ? published.substring(0, 10) : null;
  let pdfUrl = '';
  const links = e.link ? (Array.isArray(e.link) ? e.link : [e.link]) : [];
  links.forEach(function (l) {
    if (!l) return;
    const href = l.href || '';
    const type = l.type || '';
    const ltitle = l.title || '';
    if (type === 'application/pdf' || ltitle === 'pdf') pdfUrl = href;
  });
  const yr = pubDate ? Number(pubDate.substring(0, 4)) : null;
  papers.push({
    workspace_id: wsId,
    external_id: arxivId ? ('arxiv:' + arxivId) : idUrl,
    title: title,
    authors: authors,
    abstract: abstract,
    publication_date: pubDate,
    venue: 'arXiv',
    arxiv_id: arxivId || null,
    semantic_scholar_id: null,
    doi: e.doi || null,
    pdf_url: pdfUrl || null,
    paper_url: idUrl || null,
    source: 'arxiv',
    citation_count: null,
    relevance_score: scoreOf(title, abstract),
    analysis_status: 'pending',
    indexed: false,
    _year: yr
  });
});

// Semantic Scholar
let ssData = [];
try {
  const ss = $('Search Semantic Scholar').first().json;
  if (ss && Array.isArray(ss.data)) ssData = ss.data;
} catch (e) { ssData = []; }

ssData.forEach(function (p) {
  if (!p) return;
  const ext = p.externalIds || {};
  const title = (p.title || '').toString().trim();
  const abstract = (p.abstract || '').toString().trim();
  let authors = [];
  if (Array.isArray(p.authors)) authors = p.authors.map(function (a) { return { name: a.name || '', authorId: a.authorId || null }; }).filter(function (a) { return a.name; });
  let pubDate = null;
  if (p.publicationDate) pubDate = p.publicationDate;
  else if (p.year) pubDate = p.year + '-01-01';
  const yr = p.year ? Number(p.year) : (pubDate ? Number(String(pubDate).substring(0, 4)) : null);
  papers.push({
    workspace_id: wsId,
    external_id: p.paperId ? ('ss:' + p.paperId) : (ext.DOI ? ('doi:' + ext.DOI) : title),
    title: title,
    authors: authors,
    abstract: abstract,
    publication_date: pubDate,
    venue: p.venue || null,
    arxiv_id: ext.ArXiv || null,
    semantic_scholar_id: p.paperId || null,
    doi: ext.DOI || null,
    pdf_url: (p.openAccessPdf && p.openAccessPdf.url) ? p.openAccessPdf.url : null,
    paper_url: p.url || null,
    source: 'semantic_scholar',
    citation_count: (typeof p.citationCount === 'number') ? p.citationCount : null,
    relevance_score: scoreOf(title, abstract),
    analysis_status: 'pending',
    indexed: false,
    _year: yr
  });
});

const filtered = papers.filter(function (p) {
  if (!p.title) return false;
  if (yearFrom && p._year && p._year < yearFrom) return false;
  if (yearTo && p._year && p._year > yearTo) return false;
  return true;
});

return [{ json: { workspace_id: wsId, count: filtered.length, papers: filtered } }];

const input = $input.first().json;
const papers = Array.isArray(input.papers) ? input.papers : [];

function keyOf(p) {
  if (p.doi) return 'doi:' + String(p.doi).toLowerCase().trim();
  if (p.arxiv_id) return 'arxiv:' + String(p.arxiv_id).toLowerCase().trim();
  if (p.semantic_scholar_id) return 'ss:' + String(p.semantic_scholar_id).toLowerCase().trim();
  if (p.external_id) return 'ext:' + String(p.external_id).toLowerCase().trim();
  const t = (p.title || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const y = p._year || '';
  return 'ty:' + t + ':' + y;
}
function richness(p) {
  let s = 0;
  ['abstract', 'doi', 'arxiv_id', 'semantic_scholar_id', 'pdf_url', 'paper_url', 'venue', 'publication_date'].forEach(function (f) { if (p[f]) s++; });
  if (typeof p.citation_count === 'number') s++;
  if (Array.isArray(p.authors) && p.authors.length > 0) s++;
  return s;
}

const map = new Map();
let duplicates = 0;
papers.forEach(function (p) {
  const k = keyOf(p);
  if (!map.has(k)) { map.set(k, p); return; }
  duplicates++;
  const existing = map.get(k);
  const better = richness(p) > richness(existing) ? p : existing;
  const other = better === p ? existing : p;
  Object.keys(other).forEach(function (f) {
    const bv = better[f];
    const ov = other[f];
    if ((bv === null || bv === undefined || bv === '') && ov !== null && ov !== undefined && ov !== '') better[f] = ov;
  });
  const srcs = new Set();
  if (existing.source) String(existing.source).split(',').forEach(function (s) { srcs.add(s.trim()); });
  if (p.source) String(p.source).split(',').forEach(function (s) { srcs.add(s.trim()); });
  better.source = Array.from(srcs).filter(Boolean).join(',');
  better.relevance_score = Math.max(Number(existing.relevance_score) || 0, Number(p.relevance_score) || 0);
  map.set(k, better);
});

const unique = Array.from(map.values());
return [{ json: { workspace_id: input.workspace_id, count: unique.length, duplicates_removed: duplicates, papers: unique } }];

const input = $input.first().json;
const papers = Array.isArray(input.papers) ? input.papers : [];
const out = papers.map(function (p) {
  let pubDate = p.publication_date;
  if (!pubDate) pubDate = null;
  let rel = (typeof p.relevance_score === 'number') ? p.relevance_score : Number(p.relevance_score);
  if (!Number.isFinite(rel)) rel = 0;
  const rec = {
    workspace_id: Number(p.workspace_id),
    external_id: p.external_id || null,
    title: p.title || null,
    authors: Array.isArray(p.authors) ? p.authors : (p.authors ? [p.authors] : []),
    abstract: p.abstract || null,
    publication_date: pubDate,
    venue: p.venue || null,
    arxiv_id: p.arxiv_id || null,
    semantic_scholar_id: p.semantic_scholar_id || null,
    doi: p.doi || null,
    pdf_url: p.pdf_url || null,
    paper_url: p.paper_url || null,
    source: p.source || null,
    citation_count: (typeof p.citation_count === 'number') ? p.citation_count : null,
    relevance_score: rel,
    analysis_status: p.analysis_status || 'pending',
    indexed: (typeof p.indexed === 'boolean') ? p.indexed : false
  };
  return { json: rec };
});
return out;

const stored = $('Store Papers in Supabase').all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r && r.id !== undefined && r.id !== null; });
const dedup = $('Deduplicate Papers').first().json;
const wsId = dedup ? dedup.workspace_id : (stored[0] ? stored[0].workspace_id : null);
const papersOut = stored.map(function (r) {
  return {
    id: r.id,
    title: r.title,
    authors: r.authors,
    publication_date: r.publication_date,
    source: r.source,
    doi: r.doi || null,
    arxiv_id: r.arxiv_id || null,
    semantic_scholar_id: r.semantic_scholar_id || null,
    paper_url: r.paper_url || null,
    relevance_score: r.relevance_score
  };
});
return [{ json: {
  success: true,
  workspace_id: wsId,
  papers_found: dedup ? dedup.count : papersOut.length,
  papers_stored: papersOut.length,
  papers: papersOut
} }];

let details = 'Database insertion failed';
try {
  const err = $input.first().json;
  if (err && err.error) {
    if (typeof err.error === 'string') details = err.error;
    else if (err.error.message) details = err.error.message;
  }
} catch (e) {}
return [{ json: { success: false, error: 'Failed to store papers in Supabase', details: details } }];
